class SaltBottle {
     private int fizz;
     private static int towels = 3;
     public SaltBottle(int fizz) { this.fizz = fizz; }
     public void shake(int power) {
         fizz += power;
         if (fizz > 12) fizz = 12;
     }
     public void calm() {
         if (fizz > 0 && towels > 0) {
             towels--;
             fizz -= 4;
             if (fizz < 0) fizz = 0;
         }
     }
     public void show() { System.out.println(fizz + " " + towels); }
 }

