class CheerStation {
     private int energy;
     private boolean on = false;
     private static int tickets = 4;
     public CheerStation() { this(3); }
     public CheerStation(int energy) { this.energy = energy; }
     public void start() { on = energy > 0 && tickets > 0; }
     public void stop() { on = false; }
     public void chant(int rounds) {
         for (int i = 1; i <= rounds; i++) {
             if (on && energy > 0 && tickets > 0) {
                 energy--; tickets--;
                 if (energy == 0 || tickets == 0) on = false;
             } else { on = false; }
         }
     }
     public void rest(int gain) {
         energy += gain;
         if (energy > 8) energy = 8;
     }
     public void show() { System.out.println(energy + " " + on + " " + tickets); }
 }

public class Main {
    public static void main(String[] args) {
        CheerStation a = new CheerStation();
         CheerStation b = new CheerStation(5);
         a.start(); a.chant(2); a.show();
         b.start(); b.chant(3); b.show();
         a.chant(1); a.show();
         CheerStation c = new CheerStation(2); c.show();
    }
}
